  ('a55c3565-3bbb-5969-a824-cd0ea9c66150', 'Tiam tiam', null, null, null, array['porc','asiatique','four']::text[], array['{"qty":null,"unit":null,"name":"échine de porc","note":"1/3, coupée en fine lamelle (largeur 1 petit doigt)"}'::jsonb,'{"qty":null,"unit":null,"name":"poitrine de porc","note":"2/3, coupée en fine lamelle (largeur 1 petit doigt)"}'::jsonb,'{"qty":null,"unit":null,"name":"ail","note":"beaucoup"}'::jsonb,'{"qty":null,"unit":null,"name":"sauce hoisin","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"citronnelle","note":"en poudre ou coupée en fine lamelle"}'::jsonb,'{"qty":null,"unit":null,"name":"épices 5 parfums","note":"poivre de Sichuan, fenouil, badiane, cannelle, clou de girofle"}'::jsonb,'{"qty":null,"unit":null,"name":"sauce soja","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"vermicelles de riz","note":"cuites puis rincées plusieurs fois à l''eau froide pour pas qu''elles collent"}'::jsonb,'{"qty":null,"unit":null,"name":"salade à très grandes feuilles","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"concombre","note":"en tranches"}'::jsonb,'{"qty":null,"unit":null,"name":"oignon rouge","note":"en fines tranches"}'::jsonb,'{"qty":null,"unit":null,"name":"ail","note":"coupé en fines tranches, pour l''accompagnement"}'::jsonb,'{"qty":null,"unit":null,"name":"basilic thaï","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"menthe","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"coriandre","note":null}'::jsonb]::text[], array['Viande — mélanger : 1/3 échine de porc et 2/3 poitrine de porc coupées en fine lamelle (largeur 1 petit doigt), beaucoup d''ail, sauce hoisin, citronnelle en poudre ou coupée en fine lamelle, épices 5 parfums (poivre de Sichuan, fenouil, badiane, cannelle, clou de girofle), sauce soja.','Cuire au four à 180 en remuant régulièrement jusqu''à ce que la viande soit bien grillée sur le dessus.','À côté : vermicelles de riz (cuites puis rincées plusieurs fois à l''eau froide pour pas qu''elles collent), salade à très grandes feuilles, concombre en tranches, oignon rouge en fines tranches, ail coupé en fines tranches, basilic thaï, menthe, coriandre.']::text[], null, null, null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('146d6766-2ea4-5c3e-aa2a-d368ad1745f7', 'Soupe chinoise au poulet', 4, null, null, array['soupe','poulet','asiatique','robot']::text[], array['{"qty":320,"unit":"g","name":"filets de poulet","note":null}'::jsonb,'{"qty":1,"unit":"cm","name":"racine de gingembre","note":null}'::jsonb,'{"qty":200,"unit":"g","name":"carottes","note":null}'::jsonb,'{"qty":200,"unit":"g","name":"poireau","note":null}'::jsonb,'{"qty":110,"unit":"g","name":"oignon","note":null}'::jsonb,'{"qty":3,"unit":"g","name":"gousse d''ail","note":null}'::jsonb,'{"qty":2,"unit":"feuille","name":"combava séché","note":"facultatif"}'::jsonb,'{"qty":100,"unit":"g","name":"vermicelles de soja","note":null}'::jsonb,'{"qty":40,"unit":"g","name":"bouillon de poule","note":null}'::jsonb,'{"qty":150,"unit":"cl","name":"eau","note":null}'::jsonb,'{"qty":5,"unit":"cl","name":"sauce soja","note":null}'::jsonb,'{"qty":150,"unit":"g","name":"champignons de Paris","note":null}'::jsonb,'{"qty":1,"unit":"cl","name":"huile","note":null}'::jsonb,'{"qty":20,"unit":"g","name":"pousses de soja","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"basilic thaï","note":"quelques feuilles"}'::jsonb]::text[], array['Dans le bol du robot muni du couteau hachoir Ultrablade, mettez l''ail et l''oignon épluchés et coupés en morceaux. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ».','Remplacez le couteau hachoir Ultrablade par le mélangeur. Ajoutez l''huile, les carottes et le poireau émincés finement. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ». (5 min à 130°)','Pelez et hachez le gingembre. Ajoutez-le dans le bol du robot.','Ajoutez l''eau, le bouillon, les feuilles de combava et le poulet coupé en petits morceaux.','Versez la sauce soja. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ». (15 min à 95°)','Ajoutez les vermicelles et les champignons émincés. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ». (5 min à 130°)','Ajoutez les pousses de soja et le basilic ciselé et servez.']::text[], 'Étapes écrites pour le robot cuiseur (couteau Ultrablade / mélangeur).', 'https://moulinexfood.page.link/51wsdFUJHGuM8tgC8', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('f6da54f3-6c86-5708-a599-df00598f521d', 'Mijoté de poulet au chorizo', 4, null, null, array['poulet','chorizo','mijoté','robot']::text[], array['{"qty":100,"unit":"g","name":"oignon","note":null}'::jsonb,'{"qty":3,"unit":"g","name":"gousse d''ail","note":null}'::jsonb,'{"qty":200,"unit":"g","name":"filets de poulet","note":null}'::jsonb,'{"qty":100,"unit":"g","name":"chorizo","note":null}'::jsonb,'{"qty":100,"unit":"g","name":"poivron rouge","note":null}'::jsonb,'{"qty":2,"unit":"branche","name":"thym","note":null}'::jsonb,'{"qty":10,"unit":"cl","name":"vin blanc","note":null}'::jsonb,'{"qty":400,"unit":"g","name":"tomates cerises","note":"entières"}'::jsonb,'{"qty":2,"unit":"c. à café","name":"sucre","note":null}'::jsonb,'{"qty":2,"unit":"cl","name":"huile d''olive","note":null}'::jsonb,'{"qty":2,"unit":"brin","name":"persil","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"sel","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"poivre","note":null}'::jsonb]::text[], array['Dans le bol du robot muni du couteau hachoir Ultrablade, mettez l''oignon et l''ail pelés. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ».','Remplacez le couteau hachoir Ultrablade par le mélangeur. Ajoutez le poulet, le chorizo coupé en rondelles et l''huile d''olive. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ». (5 min à 130°)','Ajoutez le poivron rouge émincé en lanières, le thym, le persil, le vin blanc, les tomates cerises coupées en deux et le sucre.','Salez et poivrez. Verrouillez le couvercle avec le bouchon et appuyez sur « Start ». (20 min à 95°)','Servez chaud.']::text[], 'Étapes écrites pour le robot cuiseur (couteau Ultrablade / mélangeur).', 'https://moulinexfood.page.link/yZgJdrBfwQuL3XGL6', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('c3c5c69e-2d3a-565d-ac7b-42b7467454dc', 'Pâtes au poulet & tomates cerises', 4, null, null, array['pâtes','poulet','tomate']::text[], array['{"qty":400,"unit":"g","name":"spaghetti","note":null}'::jsonb,'{"qty":400,"unit":"g","name":"tomates cerises","note":null}'::jsonb,'{"qty":4,"unit":null,"name":"escalopes de poulet","note":null}'::jsonb,'{"qty":8,"unit":"c. à soupe","name":"parmesan râpé","note":null}'::jsonb,'{"qty":2,"unit":"gousse","name":"ail","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"basilic","note":null}'::jsonb]::text[], array['Épluchez puis hachez l''ail finement.','Ciselez finement le basilic.','Dans une casserole d''eau bouillante salée, faites cuire les pâtes selon les indications du paquet. En fin de cuisson, prélevez l''équivalent d''une petite louche d''eau de cuisson par personne, puis égouttez les pâtes.','Pendant ce temps, faites chauffer un filet d''huile d''olive dans une poêle et ajoutez-y le poulet. Salez, poivrez et laissez cuire 4 à 5 minutes sur chaque face. Réservez.','Dans la même poêle, ajoutez un filet d''huile d''olive et faites revenir l''ail émincé 2 minutes, à feu doux.','Lavez les tomates cerises et ajoutez-les dans la poêle. Faites-les revenir 2 à 3 minutes. Salez et poivrez.','Versez l''eau de cuisson des pâtes dans la poêle, puis ajoutez-y les pâtes et le parmesan. Mélangez et laissez cuire 2 à 3 minutes supplémentaires.','Ajoutez le basilic, mélangez, puis enlevez la poêle du feu.','Coupez le poulet en tranches et servez-le dans les pâtes. C''est prêt.']::text[], 'Conseils : attention à l''assaisonnement, ça peut être un peu fade (ex : rajouter du concentré de tomate ou des épices).', 'https://app.jow.com/EC0U?action=recipe&recipeId=64c3c646455c560eea66f559&source=jow', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('0d02e482-57b9-54d9-afc1-966e7f2b754c', 'Spaghetti alle vongole', 4, null, null, array['pâtes','fruits de mer','italien']::text[], array['{"qty":400,"unit":"g","name":"spaghetti","note":null}'::jsonb,'{"qty":2,"unit":"kg","name":"palourdes","note":null}'::jsonb,'{"qty":4,"unit":"gousse","name":"ail","note":null}'::jsonb,'{"qty":0.5,"unit":null,"name":"piment oiseau","note":null}'::jsonb,'{"qty":5,"unit":"c. à soupe","name":"huile d''olive","note":null}'::jsonb,'{"qty":0.5,"unit":"verre","name":"vin blanc sec","note":null}'::jsonb,'{"qty":0.5,"unit":"bouquet","name":"persil plat","note":null}'::jsonb,'{"qty":1,"unit":"pincée","name":"sel","note":"ou sel fin"}'::jsonb,'{"qty":1,"unit":"pincée","name":"poivre","note":null}'::jsonb]::text[], array['Rincez les palourdes avec beaucoup d''eau, puis mettez-les dans un saladier. Ajoutez une demi-cuillère à café de gros sel et couvrez d''eau froide. Renouvelez l''opération trois fois, jusqu''à ce qu''il n''y ait plus de résidus dans les palourdes. Rincez-les de nouveau, égouttez-les. Hachez très finement le persil avec 2 gousses d''ail, réservez dans un bol.','Dans une grande poêle creuse, faites revenir l''ail restant avec le piment oiseau, et une petite cuillerée de persil et d''ail hachés. Ajoutez les palourdes, mouillez avec le vin blanc, couvrez et laissez cuire environ 10 minutes en remuant de temps en temps, jusqu''à ce que toutes les palourdes s''ouvrent.','Une fois cuites, retirez les palourdes et filtrez leur jus de cuisson. Remettez le jus dans la poêle, faites-le cuire 5 minutes, à ce qu''il réduise d''un tiers. Gardez-le ensuite dans la poêle sur feu éteint. Pendant ce temps, ôtez la coque de la moitié des palourdes et gardez-en la moitié restante avec leur coque. Gardez toutes les palourdes (avec et sans coque) dans un saladier couvert.','En parallèle, portez à ébullition un grand volume d''eau dans une casserole haute. Dès l''ébullition salez l''eau, puis versez-y les spaghetti. Mélangez-les rapidement avec une cuillère en bois, puis laissez-les cuire pendant le temps indiqué sur le paquet (généralement les spaghetti cuisent en 9 minutes). Dès que les spaghetti sont cuits, égouttez-les « al dente » dans une passoire et versez-les dans la poêle avec le jus de cuisson des palourdes.','Remuez sur feu doux, à ce que les spaghetti s''imbibent de jus de cuisson des palourdes, ajoutez toutes les palourdes et le restant d''ail et persil hachés. Mélangez le tout quelques secondes encore à feu doux, ajoutez un tour de poivre du moulin, un filet d''huile d''olive et servez aussitôt.']::text[], null, 'https://www.750g.com/spaghetti-alle-vongole-pates-aux-palourdes-r205997.htm', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('bfe0ac94-d522-5903-a21c-c9fc7dcbcd30', 'Quiche poivrons & chorizo', 6, null, null, array['quiche','chorizo','four']::text[], array['{"qty":300,"unit":"g","name":"poivrons","note":null}'::jsonb,'{"qty":100,"unit":"g","name":"chorizo","note":null}'::jsonb,'{"qty":3,"unit":null,"name":"œufs","note":null}'::jsonb,'{"qty":100,"unit":"ml","name":"lait","note":null}'::jsonb,'{"qty":100,"unit":"ml","name":"crème liquide","note":null}'::jsonb,'{"qty":100,"unit":"g","name":"tomme","note":null}'::jsonb,'{"qty":1,"unit":null,"name":"pâte brisée","note":null}'::jsonb]::text[], array['Préchauffez le four à 180 °C. Placez la pâte dans votre moule à tarte (le nôtre fait 31 cm de diamètre) et piquez-la à l''aide d''une fourchette. Une fois le four chaud, faites pré-cuire votre pâte pendant 5 minutes.','Pendant ce temps, coupez les poivrons et le chorizo très finement. Râpez la tomme.','Dans un récipient, ajoutez : les œufs, le lait, la crème, la tomme râpée, sel, poivre et fouettez le tout énergiquement.','Une fois la pâte pré-cuite, sortez-la du four, répartissez les poivrons dans le fond avec le chorizo, puis versez l''appareil à quiche par-dessus.','Enfournez votre quiche pendant 45 minutes à 180 °C. Laissez reposer 10 minutes avant de déguster, c''est prêt ! À accompagner d''une salade verte.']::text[], 'Conseils : possibilité de précuire le mélange chorizo/poivron pour que ce soit moins gras, mais dans ce cas ne cuire la quiche que 25 min.', 'https://app.jow.com/EC0U?action=recipe&recipeId=5eda574f67aaed038d640e54&source=jow', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
