  ('f16d9feb-2236-5d61-a8da-bbefaf45a81c', 'Bucatini bisque de homard & gambas', 4, null, null, array['pâtes','fruits de mer','gambas']::text[], array['{"qty":400,"unit":"g","name":"bucatini","note":null}'::jsonb,'{"qty":400,"unit":"g","name":"bisque de homard","note":null}'::jsonb,'{"qty":10,"unit":"cl","name":"cognac","note":null}'::jsonb,'{"qty":20,"unit":null,"name":"gambas","note":null}'::jsonb,'{"qty":1,"unit":null,"name":"échalote","note":null}'::jsonb,'{"qty":1,"unit":null,"name":"oignon","note":null}'::jsonb,'{"qty":3,"unit":"gousse","name":"ail","note":null}'::jsonb,'{"qty":15,"unit":"cl","name":"vin blanc sec","note":null}'::jsonb,'{"qty":400,"unit":"g","name":"coulis de tomates","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"persil plat","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"huile d''olive","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"sel","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"poivre","note":null}'::jsonb]::text[], array['Dans une casserole faites chauffer un filet d''huile d''olive. Ajoutez l''oignon, le céleri, l''ail et l''échalote, faites-les revenir 4 à 5 minutes.','Ajoutez le cognac et le vin blanc, faites bouillir 2 minutes. Ajoutez la sauce tomate et la bisque de homard. Salez, poivrez. Portez à ébullition, baissez le feu et laissez mijoter à découvert 40 minutes.','Faites cuire les pâtes, al dente, dans un grand volume d''eau salée.','Pendant ce temps, faites chauffer un filet d''huile dans une poêle. Faites sauter les gambas 1 minute à feu vif. Salez, poivrez. Ajoutez l''ail et un peu de persil. Poursuivez la cuisson une petite minute.','Égouttez les pâtes, ajoutez la sauce et les gambas, parsemez de persil haché. C''est prêt.']::text[], 'L''étape 1 mentionne du céleri, qui n''apparaît pas dans la liste d''ingrédients d''origine.', 'https://kuri.app/NiB8Rh5c2Qb', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
