insert into public.recipes (id, title, servings, prep_min, cook_min, tags, ingredients, steps, notes, source_url, source_text, photo_url, ambiguous, created_by, created_at, updated_at) values
  ('8096f572-19ac-50b8-a8ac-f6892523446b', 'Raclette', 1, null, null, array['fromage','charcuterie','hiver']::text[], array['{"qty":250,"unit":"g","name":"fromage à raclette","note":null}'::jsonb,'{"qty":200,"unit":"g","name":"charcuterie","note":"200 à 250 g · à revoir si jambon en chiffonnade"}'::jsonb]::text[], '{}'::text[], 'Quantités par personne : ajuste le nombre de convives sur la fiche.', null, null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('83fd94b3-c8ef-5e9a-adaa-cc1a140acc4b', 'Poulet enoki', 2, null, null, array['poulet','champignons','asiatique','wok']::text[], array['{"qty":2,"unit":null,"name":"hauts de cuisses de poulet","note":null}'::jsonb,'{"qty":6,"unit":"gousse","name":"ail","note":"finement hachées"}'::jsonb,'{"qty":3,"unit":"tranche","name":"gingembre","note":"finement hachées"}'::jsonb,'{"qty":400,"unit":"g","name":"champignons enoki","note":"après avoir coupé les racines"}'::jsonb,'{"qty":2,"unit":"c. à soupe","name":"huile","note":null}'::jsonb,'{"qty":1,"unit":"c. à soupe","name":"sauce soja claire","note":null}'::jsonb,'{"qty":0.25,"unit":"c. à café","name":"sucre","note":null}'::jsonb,'{"qty":1,"unit":"c. à café","name":"maïzena","note":null}'::jsonb,'{"qty":150,"unit":"ml","name":"eau","note":null}'::jsonb,'{"qty":3,"unit":"branche","name":"ciboulette chinoise","note":"3 à 4 branches"}'::jsonb]::text[], array['Préparation des enokis : coupez la base des enokis pour séparer les champignons. Rincez-les délicatement si nécessaire.','Préparation du poulet : désossez les hauts de cuisses, retirez la peau et coupez le poulet en petits morceaux.','Sauter le poulet : faites chauffer l''huile dans un wok ou une poêle profonde sur feu vif. Ajoutez le poulet et faites-le revenir en remuant régulièrement.','Ajouter l''ail et le gingembre : incorporez l''ail et le gingembre hachés au poulet. Faites revenir jusqu''à ce qu''ils commencent à dorer.','Ajouter les enokis : ajoutez les enokis dans la poêle. Faites-les sauter pendant 3 à 4 minutes jusqu''à ce qu''ils deviennent tendres.','Préparer la sauce : mélangez la maïzena avec l''eau pour éviter les grumeaux. Versez ce mélange dans la poêle, puis ajoutez la sauce soja et le sucre. Remuez bien pour que la sauce épaississe légèrement.','Ajouter la ciboulette : coupez la ciboulette chinoise en petits morceaux et ajoutez-la à la préparation. Mélangez bien.','Servir : servez immédiatement, accompagné de riz si désiré.']::text[], null, 'https://lacuisinedebernard.com/les-enokis-sautes-lail-et-au-poule/', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('a44de1bf-5d9c-5d35-ab2d-8587bf1d6318', 'Aubergines gratinées express', 1, null, null, array['aubergine','gratin','rapide','végétarien']::text[], array['{"qty":2,"unit":null,"name":"aubergines","note":"env. 550 g"}'::jsonb,'{"qty":null,"unit":null,"name":"huile d''olive","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"origan","note":"ou thym"}'::jsonb,'{"qty":null,"unit":null,"name":"sel","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"poivre","note":null}'::jsonb,'{"qty":400,"unit":"g","name":"emmental râpé","note":null}'::jsonb]::text[], array['Couper les aubergines en belles et longues tranches d''environ 5 mm d''épaisseur.','Préchauffer le four à 190 °C.','Poser les tranches sur une ou 2 plaques de cuisson recouvertes de papier cuisson.','Verser un filet d''huile d''olive par-dessus. Puis saupoudrer d''origan (ou de thym), de sel et de poivre. Répartir l''emmental râpé par-dessus.','Enfourner 15 à 20 min. L''emmental doit commencer à dorer.','Déguster immédiatement.']::text[], null, null, null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('859fa127-9040-5f07-a821-f4554498a7e2', 'Tzatziki', 6, null, null, array['sauce','grec','concombre','sans cuisson']::text[], array['{"qty":2,"unit":null,"name":"concombres","note":"gros (ou 3 petits)"}'::jsonb,'{"qty":2,"unit":null,"name":"yaourts grecs","note":"soit 400 g de yaourt"}'::jsonb,'{"qty":1,"unit":"c. à soupe","name":"huile d''olive","note":null}'::jsonb,'{"qty":1,"unit":"c. à soupe","name":"feuilles de menthe hachées","note":"on peut mettre aussi de l''aneth ou ne pas mettre d''herbes du tout"}'::jsonb,'{"qty":4,"unit":"gousse","name":"ail","note":null}'::jsonb,'{"qty":1,"unit":"pincée","name":"sel","note":null}'::jsonb,'{"qty":1,"unit":"pincée","name":"poivre","note":null}'::jsonb]::text[], array['Épluchez les concombres. Fendez-les en deux et à l''aide d''une petite cuillère, ôtez-en les graines puis râpez-les (grille fine). Mettez-les dans une passoire et appuyez avec vos mains pour les essorer un maximum. Réservez.','Épluchez les gousses d''ail et pressez-les. Lavez, séchez et hachez la menthe.','Dans un saladier, mettez les filaments de concombre égouttés, les yaourts, la menthe, l''ail, ajoutez une cuillère à soupe d''huile d''olive et assaisonnez avec le sel et le poivre. Mélangez et réservez au réfrigérateur jusqu''au moment de servir.']::text[], null, null, null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('249b192c-9799-5c96-a059-2742ae36aa0f', 'Taboulé libanais', 4, null, null, array['salade','libanais','sans cuisson','été']::text[], array['{"qty":200,"unit":"g","name":"tomates","note":null}'::jsonb,'{"qty":40,"unit":"g","name":"boulgour","note":null}'::jsonb,'{"qty":1,"unit":null,"name":"oignon nouveau","note":null}'::jsonb,'{"qty":1.5,"unit":"bouquet","name":"persil plat","note":null}'::jsonb,'{"qty":0.5,"unit":"bouquet","name":"menthe","note":null}'::jsonb,'{"qty":1.5,"unit":null,"name":"citron","note":"pressé"}'::jsonb,'{"qty":4,"unit":"c. à soupe","name":"huile d''olive","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"sel","note":null}'::jsonb]::text[], array['Rincez le boulgour, égouttez-le. Transférez-le dans un saladier, ajoutez le jus de citron, l''huile d''olive et laissez-le gonfler 15 minutes.','Coupez le bas des tiges de persil qui ne comportent pas de feuilles, on ne les utilise pas. Émincez très finement le persil au couteau. Hachez très finement les feuilles de menthe. Coupez les tomates en petits dés.','Mélangez le persil, la menthe, les dés de tomates et l''oignon émincé avec le boulgour, salez et servez sans attendre.']::text[], null, 'https://kuri.app/lNdRtmLc2Qb', null, null, false, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('f8eae9ef-46ec-5fe7-ab26-047497e0721e', 'Feuille d''huître', null, null, null, array['à compléter']::text[], '{}'::text[], '{}'::text[], 'Import Notion — ambigu : Seulement un lien (article sur la plante « huître potagère »), pas de recette.', 'https://www.rustica.fr/choux-et-legumes-feuilles/l-huitre-potagere-mertensia-maritima,19238.html', 'Feuille d''huitre
insert into public.techniques (id, title, description, steps, pitfalls, tags, photo_url, is_example, created_by, created_at, updated_at) values
  ('4424d6d6-633e-535b-a70f-43ea7885c15b', 'Ciseler un oignon', 'Couper un oignon en petits dés réguliers, rapidement et sans larmes (ou presque). Sert de base à la plupart des plats mijotés et des sauces.', array['Couper l''oignon en deux par la racine, éplucher chaque moitié en gardant la racine : c''est elle qui tient les couches ensemble.','Poser la moitié à plat. Faire des incisions horizontales vers la racine sans la traverser.','Faire des incisions verticales, parallèles, de la pointe vers la racine, toujours sans la traverser.','Trancher perpendiculairement : les dés tombent tout seuls. Jeter la racine.']::text[], array['Couper la racine dès le début : l''oignon se défait et les dés sont irréguliers.','Un couteau mal affûté écrase les cellules et fait pleurer davantage.']::text[], array['découpe','base']::text[], null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('b59d78ba-03c3-55bf-aaeb-561a1ad9c259', 'Cuire des pâtes al dente', 'Des pâtes fermes sous la dent, qui finissent de cuire dans la sauce. Utile pour [[Spaghetti alle vongole]] et [[Pâtes au poulet & tomates cerises]].', array['Un grand volume d''eau (environ 1 litre pour 100 g de pâtes), porté à forte ébullition.','Saler franchement à l''ébullition (environ 10 g par litre) : c''est la seule occasion d''assaisonner les pâtes elles-mêmes.','Verser les pâtes, remuer dans la première minute pour qu''elles ne collent pas.','Goûter 1 à 2 minutes avant le temps indiqué sur le paquet : la pâte doit résister un peu au centre.','Prélever une louche d''eau de cuisson avant d''égoutter, puis finir la cuisson 1 à 2 minutes dans la sauce avec un peu de cette eau.']::text[], array['Rincer les pâtes : cela enlève l''amidon qui lie la sauce.','Mettre de l''huile dans l''eau : inutile, et la sauce accroche moins.','Égoutter à fond sans garder d''eau de cuisson : la sauce sera sèche.']::text[], array['cuisson','pâtes','base']::text[], null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('ceeb5dcb-b432-50e9-a56b-b67420885776', 'Déglacer', 'Récupérer les sucs caramélisés au fond d''une poêle ou d''une casserole avec un liquide (vin, alcool, bouillon, eau) pour en faire la base d''une sauce. C''est ce que fait l''étape au cognac et vin blanc de [[Bucatini bisque de homard & gambas]].', array['Après avoir saisi viande, crustacés ou aromates, retirer l''excès de gras mais garder les sucs bruns au fond.','Verser le liquide (2 à 10 cl) sur feu vif : il bout immédiatement.','Gratter le fond avec une spatule en bois pour décoller tous les sucs.','Laisser réduire de moitié avant d''ajouter le reste de la sauce.']::text[], array['Déglacer une poêle brûlée (sucs noirs) : la sauce sera amère.','Utiliser un vin qu''on ne boirait pas : son défaut se concentre en réduisant.']::text[], array['sauce','base']::text[], null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('77e3b5b7-c796-5f32-a3e2-56058499f165', 'Faire dégorger des coquillages', 'Débarrasser palourdes, coques ou moules de leur sable avant cuisson. Indispensable pour [[Spaghetti alle vongole]].', array['Rincer les coquillages à l''eau froide et jeter ceux qui sont cassés ou qui restent ouverts quand on les tapote.','Les mettre dans un saladier d''eau froide salée (environ 30 g de sel par litre, comme la mer).','Laisser reposer 20 à 30 minutes au frais : ils recrachent leur sable.','Sortir les coquillages à la main (ne pas verser le saladier : le sable retomberait dessus), changer l''eau et recommencer une ou deux fois.','Rincer une dernière fois et égoutter.']::text[], array['Eau non salée : les coquillages se referment et ne dégorgent pas.','Trop longtemps dans l''eau (plus d''une heure) : ils s''épuisent et meurent.']::text[], array['préparation','fruits de mer']::text[], null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('d6dbfc47-bcd7-540e-a10f-5a7abacf900e', 'Roux et béchamel', 'Le roux (beurre + farine cuits ensemble) épaissit les sauces. Mouillé au lait, il devient béchamel ; au bouillon, velouté.', array['Fondre 40 g de beurre à feu doux, ajouter 40 g de farine et cuire 2 minutes en remuant : le mélange mousse et sent le biscuit (roux blanc).','Verser 50 cl de lait froid d''un coup, fouetter énergiquement pour éviter les grumeaux.','Porter à frémissement en remuant sans arrêt jusqu''à épaississement (3 à 5 minutes).','Assaisonner : sel, poivre, muscade.']::text[], array['Lait chaud sur roux chaud : grumeaux garantis. L''un des deux doit être froid.','Arrêter de remuer : ça attache et brûle au fond.']::text[], array['sauce','base']::text[], null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z')
