  ('9778670a-aaaa-5e24-aaff-42e2e8d420fd', 'wine', 'Chinon rouge (exemple)', 'rouge', 'Loire', 2020, 'Fiche d''exemple : montre la gestion de cave (stock, apogée, « à boire avant »). À adapter ou supprimer.', 2, 2024, 2030, '2031-12-31', false, '{}'::text[], null, null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('895dc21f-7865-5ecf-ab23-4266ff6d2df3', 'spirit', 'Gin London Dry (exemple)', 'gin', null, null, 'Fiche d''exemple. En stock, donc compté automatiquement dans « Mon bar ».', 1, null, null, null, false, '{}'::text[], null, null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('cd1c5c38-d496-581b-adb6-13e5d4b3d153', 'spirit', 'Campari (exemple)', 'bitter', null, null, 'Fiche d''exemple. En stock, donc compté automatiquement dans « Mon bar ».', 1, null, null, null, false, '{}'::text[], null, null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('1b975f5c-3386-5418-a071-51f42aa2cb08', 'cocktail', 'Negroni', null, null, null, 'Fiche d''exemple (dosages classiques). Avec le gin et le Campari d''exemple en cave, il ne manque que le vermouth : c''est le cas « à un ingrédient près ».', 0, null, null, null, false, array['{"qty":3,"unit":"cl","name":"gin","note":null}'::jsonb,'{"qty":3,"unit":"cl","name":"Campari","note":null}'::jsonb,'{"qty":3,"unit":"cl","name":"vermouth rouge","note":null}'::jsonb]::text[], 'Dans un verre old fashioned rempli de glaçons, verser les trois ingrédients et remuer à la cuillère 20 secondes. Garnir d''un zeste d''orange.', null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('6e0f1945-fbaa-5a58-ac81-7b3af6fca4c0', 'cocktail', 'Mojito', null, null, null, 'Fiche d''exemple (dosages classiques).', 0, null, null, null, false, array['{"qty":5,"unit":"cl","name":"rhum blanc","note":null}'::jsonb,'{"qty":3,"unit":"cl","name":"jus de citron vert","note":null}'::jsonb,'{"qty":2,"unit":"c. à café","name":"sucre de canne","note":null}'::jsonb,'{"qty":6,"unit":"feuille","name":"menthe","note":null}'::jsonb,'{"qty":null,"unit":null,"name":"eau gazeuse","note":"pour compléter"}'::jsonb]::text[], 'Piler doucement la menthe avec le sucre et le citron vert dans un verre highball, ajouter le rhum, remplir de glace pilée, compléter d''eau gazeuse et remuer.', null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z'),
  ('119833aa-3f80-5321-a657-43675aaf359f', 'cocktail', 'Spritz', null, null, null, 'Fiche d''exemple (dosages classiques). À comparer avec [[Spritz PSG]].', 0, null, null, null, false, array['{"qty":6,"unit":"cl","name":"prosecco","note":null}'::jsonb,'{"qty":4,"unit":"cl","name":"Aperol","note":null}'::jsonb,'{"qty":2,"unit":"cl","name":"eau gazeuse","note":null}'::jsonb]::text[], 'Dans un grand verre à vin rempli de glaçons : prosecco, puis Aperol, puis eau gazeuse. Une tranche d''orange.', null, true, null, '2026-09-27T09:00:00Z', '2026-09-27T09:00:00Z')
